CustomField.formula:
/* Build human-readable list of Titles with labels */ LEFT(
/* Concatenated labels, each ends with ", " */ IF(INCLUDES(breg_Officer_Director_Titles__c, "AC"), "Assistant Controller, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "AS"), "Assistant Secretary, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "AT"), "Assistant Treasurer, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "C"), "Chairperson of the Board, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "CEO"), "Chief Executive Officer, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "CFO"), "Chief Financial Officer, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "CO"), "Controller, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "D"), "Director, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "EV"), "Executive Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "P"), "President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "R"), "Trustee, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "S"), "Secretary, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "SRV"), "Senior Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "T"), "Treasurer, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "V"), "Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "VC"), "Vice Chairman, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "1V"), "1st Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "9V"), "9th Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "G"), "General Partner, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "L"), "Limited Partner, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "MGR"), "Manager, ", "") & IF( INCLUDES(breg_Officer_Director_Titles__c, "Other") && NOT(ISBLANK(breg_Officer_Director_Other_Title__c)), breg_Officer_Director_Other_Title__c & ", ", "" ),
/* Remove last ", " */ LEN(
IF(INCLUDES(breg_Officer_Director_Titles__c, "AC"), "Assistant Controller, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "AS"), "Assistant Secretary, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "AT"), "Assistant Treasurer, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "C"), "Chairperson of the Board, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "CEO"), "Chief Executive Officer, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "CFO"), "Chief Financial Officer, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "CO"), "Controller, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "D"), "Director, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "EV"), "Executive Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "P"), "President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "R"), "Trustee, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "S"), "Secretary, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "SRV"), "Senior Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "T"), "Treasurer, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "V"), "Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "VC"), "Vice Chairman, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "1V"), "1st Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "9V"), "9th Vice President, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "G"), "General Partner, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "L"), "Limited Partner, ", "") & IF(INCLUDES(breg_Officer_Director_Titles__c, "MGR"), "Manager, ", "") & IF( INCLUDES(breg_Officer_Director_Titles__c, "Other") && NOT(ISBLANK(breg_Officer_Director_Other_Title__c)), breg_Officer_Director_Other_Title__c & ", ", "" )
) - 2 )
